from rest_framework import serializers, viewsets, permissions
from .models import TaskCard, BoardColumn

class TaskCardSerializer(serializers.HyperlinkedModelSerializer):
    column = serializers.HyperlinkedRelatedField(
        view_name='boardcolumn-detail',
        queryset=BoardColumn.objects.none()
    )

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        request = self.context.get('request')
        if request and hasattr(request, 'user'):
            self.fields['column'].queryset = BoardColumn.objects.filter(
                board__project__team__members=request.user
            )

    class Meta:
        model = TaskCard
        fields = ('url', 'id', 'title', 'description', 'column')

class TaskCardViewSet(viewsets.ModelViewSet):
    serializer_class = TaskCardSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return TaskCard.objects.filter(project__team__members=self.request.user)
